Aqui está um script em Python para encontrar o maior número primo menor que 1000:

```python
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def largest_prime_below(limit):
    for num in range(limit - 1, 1, -1):
        if is_prime(num):
            return num
    return None

result = largest_prime_below(1000)
print(f"O maior número primo menor que 1000 é {result}.")
```

